17	use mod_quiz\form\preflight_check_form;
18	use mod_quiz\local\access_rule_base;
19	use mod_quiz\quiz_settings;
20	
21	/**
22	 * A rule implementing the offlineattempts check.
23	 *
24	 * @package    quizaccess_offlineattempts
25	 * @copyright  2016 Juan Leyva
26	 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
27	 * @since      Moodle 3.2
28	 */
29	class quizaccess_offlineattempts extends access_rule_base {
30	
31	    public static function make(quiz_settings $quizobj, $timenow, $canignoretimelimits) {
32	        global $CFG;
33	
34	        // If mobile services are off, the user won't be able to use any external app.
35	        if (empty($CFG->enablemobilewebservice) or empty($quizobj->get_quiz()->allowofflineattempts)) {
36	            return null;
37	        }
38	
39	        return new self($quizobj, $timenow);
40	    }
41	
42	    public function is_preflight_check_required($attemptid) {
43	        global $SESSION, $DB;
44	
45	        // First, check if the user did something offline.
46	        if (!empty($attemptid)) {
47	            $timemodifiedoffline = $DB->get_field('quiz_attempts', 'timemodifiedoffline', ['id' => $attemptid]);
48	            if (empty($timemodifiedoffline)) {
49	                return false;
50	            }
51	            return empty($SESSION->offlineattemptscheckedquizzes[$this->quiz->id]);
52	        } else {
