69	
70	        // Process quizsettings.
71	        $data = (object) $data;
72	        $data->quizid = $this->get_new_parentid('quiz'); // Update quizid with new reference.
73	        $data->cmid = $this->task->get_moduleid();
74	
75	        unset($data->id);
76	        $data->timecreated = $data->timemodified = time();
77	        $data->usermodified = $USER->id;
78	
79	        // Do not use template if it is no longer enabled.
80	        if ($data->requiresafeexambrowser == settings_provider::USE_SEB_TEMPLATE &&
81	                !$DB->record_exists(template::TABLE, ['id' => $data->templateid, 'enabled' => '1'])) {
82	            $data->templateid = 0;
