1	// Análisis estático de archivos de prueba Playwright, SIN IA y sin depender del generador.
2	// Extrae, por prueba: título, línea, cantidad de asserts, matchers usados, omisiones, opciones de captura.
3	// Es deliberadamente simple (léxico + balanceo de llaves) para que un humano pueda auditarlo línea por línea.
4	
5	export const MATCHERS_DEBILES = new Set([
6	  'toBeTruthy', 'toBeFalsy', 'toBeDefined', 'toBeUndefined', 'toBeNull', 'toBeNaN', 'toBeAttached',
7	  'toBeGreaterThanOrEqual', 'toBeLessThanOrEqual', 'toBeInstanceOf', 'anything', 'any',
8	]);
9	
10	/** Quita comentarios y contenido de strings (conserva longitudes para mapear líneas). */
11	function enmascarar(src) {
12	  let out = '';
13	  let i = 0;
14	  while (i < src.length) {
