1	// CONTROL DE VERIFICACIÓN HONESTA
2	// Independiente de quien genera las pruebas: no usa IA, no importa nada del generador, y compara contra
3	// referencias que el pipeline NO puede escribir solo:
4	//   - factory/honestidad/manifiesto.json TAL COMO ESTÁ EN LA RAMA main (git show main:...), no la copia de trabajo
5	//   - visual/lineas-base/APROBACIONES.json TAL COMO ESTÁ EN main + aprobaciones nuevas firmadas por humano
6	// Bloquea (exit 1) ante cualquier hallazgo. No advierte: o pasa, o no hay pull request.
7	//
8	// Se ejecuta desde la versión de main (factory/lib/auditor.mjs), no desde la copia de trabajo auditada.
9	//
10	// Uso: node factory/honestidad/verificar.mjs [--resultados <resultados.json>] [--sin-feature <resultados.json>]
11	//                                            [--plan <plan.json>] [--salida <honestidad.log>] [--json <hallazgos.json>]
12	import fs from 'node:fs';
13	import path from 'node:path';
14	import crypto from 'node:crypto';
15	import { execSync } from 'node:child_process';
16	import { fileURLToPath } from 'node:url';
17	import { analizarArchivo, idPrueba } from './analisis.mjs';
18	
19	const RAIZ = process.env.HONESTIDAD_RAIZ || path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
20	const REF = process.env.HONESTIDAD_REF || 'main';
21	const MANIFIESTO = 'factory/honestidad/manifiesto.json';
22	const APROBACIONES = 'visual/lineas-base/APROBACIONES.json';
23	const CONFIG = 'playwright.config.ts';
24	const DIR_AUDITOR = 'factory/honestidad';
25	const LANZADOR = 'factory/lib/auditor.mjs';
26	// Datos, no código: `aprobar-pruebas` los escribe en la rama y el auditor siempre los lee de main.
27	const DATOS_AUDITOR = new Set([MANIFIESTO, `${DIR_AUDITOR}/aprobaciones.log`]);
28	
29	const arg = (n) => { const i = process.argv.indexOf(n); return i > 0 ? process.argv[i + 1] : null; };
30	const enRef = (p) => { try { return execSync(`git show ${REF}:${p}`, { cwd: RAIZ, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }); } catch { return null; } };
31	const json = (s, def) => { try { return s ? JSON.parse(s) : def; } catch { return def; } };
32	const sha = (f) => crypto.createHash('sha256').update(fs.readFileSync(f)).digest('hex');
33	
34	function listarPruebas() {
35	  const out = [];
36	  const recorrer = (d) => {
37	    const abs = path.join(RAIZ, d);
38	    if (!fs.existsSync(abs)) return;
39	    for (const e of fs.readdirSync(abs, { withFileTypes: true })) {
40	      const rel = path.join(d, e.name);
41	      if (e.isDirectory() && e.name !== 'node_modules') recorrer(rel);
42	      else if (e.name.endsWith('.spec.ts')) out.push(rel);
43	    }
44	  };
45	  recorrer('factory/regresion');
46	  for (const s of fs.existsSync(path.join(RAIZ, 'salidas')) ? fs.readdirSync(path.join(RAIZ, 'salidas')) : []) recorrer(`salidas/${s}/pruebas`);
47	  return out.sort();
48	}
49	
50	export function construirManifiesto() {
51	  const pruebas = {};
52	  const omisiones = {};
53	  for (const f of listarPruebas()) {
54	    const a = analizarArchivo(f, fs.readFileSync(path.join(RAIZ, f), 'utf8'));
55	    for (const p of a.pruebas) pruebas[idPrueba(p)] = { asserts: p.asserts, fuertes: p.fuertes, soft: p.soft, matchers: p.matchers, capturas: p.capturas, mascaras: p.mascaras, opcionesCaptura: p.opcionesCaptura, modificador: p.modificador, tags: p.tags };
56	    if (a.omisiones.length) omisiones[f] = a.omisiones.map((o) => o.texto);
57	  }
58	  const cfg = fs.readFileSync(path.join(RAIZ, CONFIG), 'utf8');
59	  return { pruebas, omisiones, umbralVisual: umbral(cfg) };
60	}
61	
62	const umbral = (cfg) => ({
63	  threshold: Number((cfg.match(/threshold:\s*([\d.]+)/) || [])[1]),
64	  maxDiffPixelRatio: Number((cfg.match(/maxDiffPixelRatio:\s*([\d.]+)/) || [])[1]),
65	  retries: Number((cfg.match(/retries:\s*(\d+)/) || [])[1]),
66	});
67	
68	/** Texto de la configuración sin comentarios ni diferencias de espacios: cambiar un comentario no es un cambio. */
69	const normalizarConfig = (s) => s.replace(/^\s*\/\/.*$/gm, '').replace(/\s\/\/.*$/gm, '').replace(/\s+/g, ' ').trim();
70	
71	function archivosDelAuditor() {
72	  const enTrabajo = fs.readdirSync(path.join(RAIZ, DIR_AUDITOR), { recursive: true, withFileTypes: true })
73	    .filter((e) => e.isFile()).map((e) => path.relative(RAIZ, path.join(e.parentPath ?? e.path, e.name)));
74	  const enMain = execSync(`git ls-tree -r --name-only ${REF} -- ${DIR_AUDITOR}`, { cwd: RAIZ, encoding: 'utf8' }).split('\n').filter(Boolean);
75	  return [...new Set([...enTrabajo, ...enMain, LANZADOR])].filter((f) => !DATOS_AUDITOR.has(f)).sort();
76	}
77	
78	export function verificar({ resultados, sinFeature, plan } = {}) {
79	  const H = [];
80	  const hallazgo = (regla, donde, detalle) => H.push({ regla, donde, detalle });
81	  const ref = json(enRef(MANIFIESTO), null);
82	  const actual = construirManifiesto();
83	
84	  // 0) Las herramientas de verificación son las de main: quien se audita no puede cambiar al auditor ni qué se ejecuta.
85	  for (const f of archivosDelAuditor()) {
86	    const abs = path.join(RAIZ, f);
87	    const copia = fs.existsSync(abs) ? fs.readFileSync(abs, 'utf8') : null;
88	    if (copia !== enRef(f)) hallazgo('AUDITOR-ALTERADO', f, `Difiere de ${REF}. Los cambios al auditor se hacen en ${REF}, no en la rama que se audita.`);
89	  }
90	  const cfgRef = enRef(CONFIG);
91	  if (cfgRef === null || normalizarConfig(cfgRef) !== normalizarConfig(fs.readFileSync(path.join(RAIZ, CONFIG), 'utf8'))) {
92	    hallazgo('CONFIG-PRUEBAS-ALTERADA', CONFIG, `Difiere de ${REF}: podría excluir pruebas (testMatch, testIgnore, grep, projects) o alterar cómo se reportan.`);
93	  }
94	
95	  if (!ref) hallazgo('SIN-REFERENCIA', `${REF}:${MANIFIESTO}`, `No existe manifiesto aprobado en ${REF}. Sin referencia no se puede afirmar que nada se debilitó.`);
96	  const base = ref || { pruebas: {}, omisiones: {}, umbralVisual: actual.umbralVisual };
97	
98	  // 1) Pruebas aprobadas que desaparecieron o verifican menos que antes.
99	  for (const [id, a] of Object.entries(base.pruebas)) {
100	    const b = actual.pruebas[id];
101	    if (!b) { hallazgo('PRUEBA-ELIMINADA', id, 'Estaba en el manifiesto aprobado y ya no existe (¿renombrada o borrada?).'); continue; }
102	    if (b.asserts < a.asserts) hallazgo('ASSERTS-REDUCIDOS', id, `Tenía ${a.asserts} expect(), ahora ${b.asserts}.`);
103	    if (b.fuertes < a.fuertes) hallazgo('MATCHER-DEBILITADO', id, `Matchers fuertes: ${a.fuertes} -> ${b.fuertes}. Antes: [${a.matchers.join(', ')}] Ahora: [${b.matchers.join(', ')}]`);
104	    if (b.soft > a.soft) hallazgo('ASSERT-SOFT', id, `expect.soft no detiene la prueba: ${a.soft} -> ${b.soft}.`);
105	    if (b.capturas < a.capturas) hallazgo('CAPTURA-ELIMINADA', id, `Comparaciones visuales: ${a.capturas} -> ${b.capturas}.`);
106	    if (b.mascaras > a.mascaras) hallazgo('MASCARA-AGREGADA', id, `Máscaras en capturas: ${a.mascaras} -> ${b.mascaras}. Una máscara nueva puede tapar una rotura.`);
107	    if (JSON.stringify(b.opcionesCaptura) !== JSON.stringify(a.opcionesCaptura)) hallazgo('UMBRAL-POR-PRUEBA', id, `Opciones de tolerancia: [${a.opcionesCaptura}] -> [${b.opcionesCaptura}].`);
108	    if (b.modificador && b.modificador !== a.modificador) hallazgo('OMITIDA', id, `Ahora es test.${b.modificador}().`);
109	  }
110	
111	  // 2) Reglas que aplican a TODAS las pruebas (también a las nuevas que trae un spec).
112	  for (const f of listarPruebas()) {
113	    const a = analizarArchivo(f, fs.readFileSync(path.join(RAIZ, f), 'utf8'));
114	    for (const o of a.omisiones) {
115	      if (o.tipo === 'only') hallazgo('TEST-ONLY', `${f}:${o.linea}`, `${o.texto} — excluye al resto de la suite.`);
116	      else if (!(base.omisiones[f] || []).includes(o.texto)) hallazgo('OMISION-NUEVA', `${f}:${o.linea}`, `${o.texto} — omisión no aprobada.`);
117	    }
118	    for (const p of a.pruebas) {
119	      const donde = `${f}:${p.linea} «${p.titulo}»`;
120	      if (p.asserts === 0) hallazgo('SIN-ASSERTS', donde, 'La prueba no tiene ningún expect(): no puede fallar por comportamiento.');
121	      if (p.triviales.length) hallazgo('ASSERT-TRIVIAL', donde, `Afirma sobre un literal: ${p.triviales.join(' ; ')}`);
122	      if (p.sinAwait.length) hallazgo('ASSERT-SIN-AWAIT', donde, `Aserción asíncrona sin await (${p.sinAwait.join(', ')}): nunca hace fallar la prueba.`);
123	      if (p.tragaErrores) hallazgo('ERROR-TRAGADO', donde, 'Un .catch/try vacío puede convertir un fallo en éxito.');
124	      if (p.mockRed) hallazgo('RED-SIMULADA', donde, 'page.route/route.fulfill: la prueba verificaría una respuesta inventada, no Moodle.');
125	      if (p.modificador && !base.pruebas[idPrueba(p)]) hallazgo('OMITIDA', donde, `test.${p.modificador}() en prueba nueva.`);
126	    }
127	  }
128	
129	  // 3) Configuración global de la suite.
130	  const u0 = base.umbralVisual, u1 = actual.umbralVisual;
131	  if (u1.threshold > u0.threshold || u1.maxDiffPixelRatio > u0.maxDiffPixelRatio) hallazgo('UMBRAL-RELAJADO', CONFIG, `threshold ${u0.threshold}->${u1.threshold}, maxDiffPixelRatio ${u0.maxDiffPixelRatio}->${u1.maxDiffPixelRatio}`);
132	  if (u1.retries > u0.retries) hallazgo('REINTENTOS', CONFIG, `retries ${u0.retries}->${u1.retries}: los reintentos esconden pruebas inestables.`);
133	
134	  // 4) Líneas base visuales: toda imagen debe coincidir con una aprobación firmada.
135	  const aprobRef = json(enRef(APROBACIONES), {});
136	  const aprobAct = json(fs.existsSync(path.join(RAIZ, APROBACIONES)) ? fs.readFileSync(path.join(RAIZ, APROBACIONES), 'utf8') : null, {});
137	  const dirLB = path.join(RAIZ, 'visual/lineas-base');
138	  for (const png of fs.existsSync(dirLB) ? fs.readdirSync(dirLB).filter((f) => f.endsWith('.png')) : []) {
139	    const h = sha(path.join(dirLB, png));
140	    const aR = aprobRef[png], aA = aprobAct[png];
141	    if (aR && aR.sha256 === h) continue; // idéntica a la aprobada en main
142	    if (aR && aR.sha256 !== h) {
143	      // Cambió una línea base existente. Dos únicos caminos legítimos:
144	      //  a) aprobación humana nueva (origen humano, razón, hash exacto);
